<script setup>
import {Head,Link,router,usePage,useForm} from '@inertiajs/vue3';import {ref,watch} from 'vue';import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';import ManagementPager from '../../Components/ManagementPager.vue';import {useI18n} from '../../lib/i18n.js';
const {t}=useI18n();
const props=defineProps({collections:Object,filters:Object}),query=ref(props.filters?.q??'');
const searching=ref(false),searchErrors=ref({});
watch(()=>props.filters?.q,value=>{query.value=value??'';});
function search(){
 if(searching.value)return;
 const q=String(query.value??'').trim();query.value=q;searchErrors.value={};
 router.get('/admin/collections',{q},{preserveState:true,replace:true,onStart:()=>{searching.value=true;},onError:errors=>{searchErrors.value=errors;},onFinish:()=>{searching.value=false;}});
}
function clearSearch(){query.value='';search();}
</script><template><Head :title="t('Collection administration')"/><AppLayout :title="t('Collection administration')"><template #actions><Link href="/admin/users" class="button secondary">{{t('Account administration')}}</Link></template><Errors :errors="searchErrors"/><form class="admin-search panel" :aria-busy="searching" @submit.prevent="search"><label>{{t('Search collections')}}<input v-model="query" type="search" maxlength="100"/></label><button class="button" :disabled="searching">{{t('Search')}}</button><button v-if="query||filters?.q" type="button" class="button secondary" :disabled="searching" @click="clearSearch">{{t('Clear search')}}</button></form><section class="panel"><p v-if="!collections.data.length">{{t('No collections match your search.')}}</p><article v-for="item in collections.data" :key="item.id" class="admin-row"><div><h2>{{item.title}}</h2><p>{{item.description}}</p><small>{{t('{count} words',{count:item.words_count})}} · {{t(item.share_uuid?'Link sharing on':'Link sharing off')}}</small></div><Link :href="`/admin/collections/${item.id}`" class="button secondary">{{t('Inspect collection')}}</Link></article><ManagementPager :page="collections"/></section></AppLayout></template><style scoped>.admin-search{display:flex;align-items:flex-end;gap:12px;margin-bottom:20px}.admin-search label{flex:1;margin:0}.admin-row{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:18px 0;border-bottom:1px solid #ddd}.admin-row h2{font-size:1.1rem}.admin-row p{overflow-wrap:anywhere}@media(max-width:600px){.admin-row,.admin-search{flex-direction:column;align-items:stretch}}.admin-search{margin-bottom:20px}@media(max-width:600px){.admin-search .button{width:100%}}</style>